frappe.listview_settings['RQ Job'] = {
    onload: function(listview) {
        // Check if the logged in user is Administrator
        if (frappe.session.user !== "Administrator") {
            return;
        }
        // Adding a custom menu item to the list view page
        listview.page.add_menu_item(__("Clear Queue"), function() {
            frappe.prompt(
                [
                    {
                        fieldname: "queue_type",
                        fieldtype: "Select",
                        label: "Queue Type",
                        options: "default\nshort\nlong",
                        reqd: 1,
                        default: "default"
                    }
                ],
                function(values) {
                    frappe.call({
                        method: "tnc_frappe_custom_app.queue_management.clear_queue",  // Update with your actual module path
                        args: {
                            queue_type: values.queue_type
                        },
                        callback: function(response) {
                            frappe.msgprint(response.message);
                            // Optionally refresh the list view to reflect changes
                            listview.refresh();
                        }
                    });
                },
                __("Clear Queue"),
                __("Clear")
            );
        });
    }
};

frappe.ui.form.on('Employee', {
    refresh(frm) {
        // Handle defaults
        if (frm.doc.__islocal) {
            if (!frm.doc.date_of_joining) frm.set_value('date_of_joining', '2020-01-01');
            if (!frm.doc.date_of_birth) frm.set_value('date_of_birth', '2000-01-01');
        }

        // Show Button only if Teacher is not set and employee exists
        if (!frm.doc.custom_teacher && !frm.is_new() && frappe.user.has_role('TNC Manager')) {
            frm.add_custom_button(__('Create Teacher'), function() {
                if (!frm.doc.personal_email || !frm.doc.employee_name) {
                    frappe.msgprint(__('Mandatory: <b>Employee Name</b> and <b>Personal Email</b>.'));
                    return;
                }
                open_teacher_activity_dialog(frm);
            }).addClass('btn-primary');
        }
    }
});

