function open_teacher_activity_dialog(frm) {
    let d = new frappe.ui.Dialog({
        title: 'Select Teacher Activities',
        fields: [
            {
                label: 'Activities',
                fieldname: 'activities',
                fieldtype: 'Table',
                fields: [
                    {
                        fieldtype: 'Link',
                        fieldname: 'activity_name',
                        options: 'Activity',
                        label: 'Activity',
                        in_list_view: 1,
                        reqd: 1,
                        get_query: function() {
                            return { filters: { 'enable': 1 } };
                        },
                        change: function() {
                            // 1. Target the grid_row specifically
                            let grid_row = this.grid_row; 
                            let row = grid_row.doc;

                            if (row.activity_name) {
                                frappe.db.get_value('Activity', row.activity_name, 'uom', (r) => {
                                    if (r && r.uom) {
                                        // 2. Set the data on the local doc object
                                        row.uom = r.uom;

                                        // 3. Force the specific field in that specific row to repaint
                                        grid_row.refresh_field('uom');

                                        // 4. Update the background model to ensure it saves when clicking 'Primary Action'
                                        frappe.model.set_value(row.doctype, row.name, 'uom', r.uom);

                                        console.log("Updated specific grid row cell: ", r.uom);
                                    }
                                });
                            }
                        }
                    },
                    {
                        fieldtype: 'Data',
                        fieldname: 'uom',
                        label: 'UOM',
                        read_only: 1,
                        in_list_view: 1
                    },
                    {
                        fieldtype: 'Currency',
                        fieldname: 'rate',
                        label: 'Rate',
                        in_list_view: 1,
                        reqd: 1
                    }
                ]
            }
        ],
        primary_action_label: 'Confirm & Create',
        primary_action(values) {
            if (!values.activities || values.activities.length === 0) {
                frappe.msgprint(__('Please add at least one activity.'));
                return;
            }
            d.hide(); 
            frappe.confirm(__('Are you sure you want to create a Teacher?'), () => {
                frappe.call({
                    method: "institute_management_360ithub.institute_management_360ithub.doctype.teacher.teacher.create_teacher_from_employee",
                    args: {
                        employee_id: frm.doc.name,
                        activities: values.activities
                    },
                    freeze: true,
                    callback: function(r) {
                        if (r.message) {
                            frappe.show_alert({message: __('Teacher Linked Successfully'), indicator: 'green'});
                            frm.reload_doc();
                        }
                    }
                });
            }, () => {
                d.show(); 
            });
        }
    });
    d.show();
}
